#include <vector>
#include <algorithm>

class Solution {
    int dfs(int u, const std::vector<std::vector<int>>& adj, const std::vector<int>& informTime) {
        int curMax = 0;
        for (int v : adj[u]) {
            curMax = std::max(curMax, dfs(v, adj, informTime));
        }
        return informTime[u] + curMax;
    }
public:
    int numOfMinutes(int n, int headID, std::vector<int>& manager, std::vector<int>& informTime) {
        std::vector<std::vector<int>> adj(n);
        for (int i = 0; i < n; ++i) {
            if (manager[i] != -1) adj[manager[i]].push_back(i);
        }
        return dfs(headID, adj, informTime);
    }
};

import java.util.*;

class Solution {
    private int dfs(int u, List<List<Integer>> adj, int[] informTime) {
        int curMax = 0;
        for (int v : adj.get(u)) {
            curMax = Math.max(curMax, dfs(v, adj, informTime));
        }
        return informTime[u] + curMax;
    }
    public int numOfMinutes(int n, int headID, int[] manager, int[] informTime) {
        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < n; i++) {
            if (manager[i] != -1) adj.get(manager[i]).add(i);
        }
        return dfs(headID, adj, informTime);
    }
}

var numOfMinutes = function(n, headID, manager, informTime) {
    const adj = Array.from({ length: n }, () => []);
    for (let i = 0; i < n; i++) {
        if (manager[i] !== -1) adj[manager[i]].push(i);
    }
    const dfs = (u) => {
        let curMax = 0;
        for (const v of adj[u]) {
            curMax = Math.max(curMax, dfs(v));
        }
        return informTime[u] + curMax;
    };
    return dfs(headID);
};
